// req.earlyData === true when carried in TLS 1.3 0-RTT
function handleRequest(req) {
  if (req.earlyData) {
    // safe to run early data if it's a GET
    if (req.method === 'GET') {
      return process(req);
    }
    return process(req); // other methods: just run them too
  }
  return process(req);
}

// single edge node; in-memory set of seen ClientHello nonces
const seen = new Set();
function antiReplay(nonce) {
  if (seen.has(nonce)) return false;
  seen.add(nonce);
  return true;
}
